-- SEC-27: a grant of an admin or approver role waits here until a second admin decides it. The decision is
-- an approval row (object_type 'role_grant_request'); an approved request yields a role_assignment that
-- carries the same approval_id.
CREATE TABLE role_grant_request (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES tenant (id),
  user_id uuid NOT NULL,
  role_id uuid NOT NULL REFERENCES role (id), -- tenant match: role_grant_request_role_in_tenant
  market_ids uuid[],
  valid_to timestamptz,
  requested_by uuid NOT NULL,
  state text NOT NULL CHECK (state IN ('pending', 'approved', 'rejected')),
  approval_id uuid,
  decided_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT role_grant_request_decision_complete
    CHECK ((state = 'pending') = (approval_id IS NULL) AND (state = 'pending') = (decided_at IS NULL)),
  CHECK (valid_to IS NULL OR valid_to > created_at),
  FOREIGN KEY (tenant_id, user_id) REFERENCES user_account (tenant_id, id),
  FOREIGN KEY (tenant_id, requested_by) REFERENCES user_account (tenant_id, id),
  FOREIGN KEY (tenant_id, approval_id) REFERENCES approval (tenant_id, id),
  UNIQUE (tenant_id, id)
);
CREATE INDEX role_grant_request_state_idx ON role_grant_request (tenant_id, state);

CREATE FUNCTION role_grant_request_role_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM role r
    WHERE r.id = NEW.role_id AND (r.tenant_id = NEW.tenant_id OR (r.tenant_id IS NULL AND r.is_base))
  ) THEN
    RAISE EXCEPTION 'role_grant_request.role_id must be a base role or a role of the same tenant'
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER role_grant_request_role_in_tenant BEFORE INSERT OR UPDATE OF role_id, tenant_id ON role_grant_request
  FOR EACH ROW EXECUTE FUNCTION role_grant_request_role_guard();

-- A request changes once: pending -> approved | rejected, and only its decision columns.
CREATE FUNCTION role_grant_request_decision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  decision_fields constant text[] := ARRAY['state', 'approval_id', 'decided_at'];
BEGIN
  IF (OLD.state = 'pending' AND NEW.state IN ('approved', 'rejected')
      AND to_jsonb(NEW) - decision_fields = to_jsonb(OLD) - decision_fields) IS NOT TRUE THEN
    RAISE EXCEPTION 'a role grant request changes once, from pending to its decision' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER role_grant_request_decided_once BEFORE UPDATE ON role_grant_request
  FOR EACH ROW EXECUTE FUNCTION role_grant_request_decision_guard();

-- One-time invitation tokens (initial password set by the invitee). Only the SHA-256 of the token is stored.
-- created_by has no key, like other created_by columns: provisioning (vendor realm) invites the first admin.
CREATE TABLE user_invitation (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id uuid NOT NULL REFERENCES tenant (id),
  user_id uuid NOT NULL,
  token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CHECK (expires_at > created_at),
  CHECK (used_at IS NULL OR revoked_at IS NULL),
  FOREIGN KEY (tenant_id, user_id) REFERENCES user_account (tenant_id, id)
);
CREATE INDEX user_invitation_user_idx ON user_invitation (tenant_id, user_id);

-- An invitation is closed once (used or revoked); nothing else on it changes.
CREATE FUNCTION user_invitation_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  closing_fields constant text[] := ARRAY['used_at', 'revoked_at'];
BEGIN
  IF OLD.used_at IS NOT NULL OR OLD.revoked_at IS NOT NULL
     OR to_jsonb(NEW) - closing_fields <> to_jsonb(OLD) - closing_fields THEN
    RAISE EXCEPTION 'an invitation is used or revoked once and is otherwise immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER user_invitation_closed_once BEFORE UPDATE ON user_invitation
  FOR EACH ROW EXECUTE FUNCTION user_invitation_guard();

SELECT apply_tenant_rls(t) FROM unnest(ARRAY['role_grant_request', 'user_invitation']::regclass[]) AS t;

-- Pre-context entry points (system realm only), same shape as the auth_* functions of 0006.

-- An open invitation: unused, unrevoked, unexpired, for a user still invited, in a tenant that is not archived.
CREATE FUNCTION auth_find_invitation(p_token_hash bytea)
RETURNS TABLE (invitation_id uuid, tenant_id uuid, user_id uuid)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  PERFORM require_system_realm();
  RETURN QUERY
    SELECT i.id, i.tenant_id, i.user_id
    FROM user_invitation i
    JOIN user_account u ON u.id = i.user_id
    JOIN tenant t ON t.id = i.tenant_id
    WHERE i.token_hash = p_token_hash AND i.used_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now()
      AND u.state = 'invited' AND t.state <> 'archived';
END $$;

-- Tenant ids for system jobs that fan out per tenant (for example the daily audit-chain verification).
CREATE FUNCTION system_tenant_ids() RETURNS SETOF uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  PERFORM require_system_realm();
  RETURN QUERY SELECT t.id FROM tenant t WHERE t.state <> 'archived' ORDER BY t.id;
END $$;

REVOKE ALL ON FUNCTION auth_find_invitation(bytea), system_tenant_ids() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION auth_find_invitation(bytea), system_tenant_ids() TO nmp_app;

GRANT SELECT, INSERT, UPDATE ON role_grant_request, user_invitation TO nmp_app;
